mapper.select:
SELECT
    COUNT(DISTINCT pm.PROJECT_ID)
FROM
    project_master pm
    LEFT JOIN PROJECT_EMP pe ON (
        pm.PROJECT_ID = pe.PROJECT_ID
        AND pm.DOMAIN_ID = pe.DOMAIN_ID
        AND pe.PROJECT_EMP_CD = 'CM004CD002'
        AND pe.EMAIL = #{email}
    )

    pm.DOMAIN_ID = #{domainId}
    AND pm.COMPANY_CD = #{companyCd}
    AND (
        pm.PROJECT_OWNER_MEMBER_ID = #{email}
        OR pe.EMAIL = #{email}
    )

        AND pm.DEL_YN = #{delYn}



        AND pm.PROJECT_NM LIKE CONCAT('%', #{projectNm}, '%')



        AND pm.PROJECT_STATE_CD = #{projectStateCd}



        AND pm.PROJECT_START_DT >= #{projectStartDt}



        AND pm.PROJECT_END_DT  <= #{projectEndDt}

SELECT DISTINCT pm.DOMAIN_ID , pm.COMPANY_CD , pm.PROJECT_ID , pm.PROJECT_NM , pm.PROJECT_DESC , pm.PROJECT_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM008', pm.PROJECT_STATE_CD, pm.COMPANY_CD, pm.DOMAIN_ID) AS PROJECT_STATE_NM , pm.PROJECT_CATEGORY_CD , pm.PROJECT_START_DT , pm.PROJECT_END_DT , pm.PROJECT_OWNER_MEMBER_ID , SF_GET_MEMBER_NAME(pm.PROJECT_OWNER_MEMBER_ID) AS PROJECT_OWNER_MEMBER_NM , pm.DEL_YN , pm.UPDATE_USR , CONVERT_TZ(pm.UPDATE_DT, '+00:00', '+09:00') AS UPDATE_DT , pm.CREATE_USR , CONVERT_TZ(pm.CREATE_DT, '+00:00', '+09:00') AS CREATE_DT , pe.EMAIL FROM project_master pm LEFT JOIN PROJECT_EMP pe ON ( pm.PROJECT_ID = pe.PROJECT_ID AND pm.DOMAIN_ID = pe.DOMAIN_ID AND pe.PROJECT_EMP_CD = 'CM004CD002' AND pe.EMAIL = #{email} )
pm.DOMAIN_ID = #{domainId} AND pm.COMPANY_CD = #{companyCd} AND ( pm.PROJECT_OWNER_MEMBER_ID = #{email} OR pe.EMAIL = #{email} )
AND pm.DEL_YN = #{delYn}
AND pm.PROJECT_NM LIKE CONCAT('%', #{projectNm}, '%')
AND pm.PROJECT_STATE_CD = #{projectStateCd}
AND pm.PROJECT_START_DT >= #{projectStartDt}
AND pm.PROJECT_END_DT <= #{projectEndDt}
ORDER BY pm.CREATE_DT
LIMIT #{start}, #{length}

mapper.insert:
        INSERT INTO PROJECT_MASTER (
            DOMAIN_ID
            , COMPANY_CD
            , PROJECT_ID
            , PROJECT_NM
            , PROJECT_DESC
            , PROJECT_STATE_CD
            , PROJECT_CATEGORY_CD
            , PROJECT_START_DT
            , PROJECT_END_DT
            , PROJECT_OWNER_MEMBER_ID
            , DEL_YN
			, UPDATE_USR
			, UPDATE_DT
			, CREATE_USR
			, CREATE_DT
		)
		VALUES (
            #{domainId}
            , #{companyCd}
            , #{projectId}
            , #{projectNm}
            , #{projectDesc}
            , #{projectStateCd}
            , #{projectCategoryCd}
            , #{projectStartDt}
            , #{projectEndDt}
            , #{projectOwnerMemberId}
            , #{delYn}
            , #{updateUsr}
            , NOW()
            , #{createUsr}
            , NOW()
        )

mapper.update:
UPDATE PROJECT_MASTER SET
    PROJECT_NM              = #{projectNm}
    , PROJECT_DESC          = #{projectDesc}
    , PROJECT_STATE_CD      = #{projectStateCd}
    , PROJECT_CATEGORY_CD   = #{projectCategoryCd}
    , PROJECT_START_DT      = #{projectStartDt}
    , PROJECT_END_DT        = #{projectEndDt}
    , PROJECT_OWNER_MEMBER_ID = #{projectOwnerMemberId}
    , UPDATE_USR            = #{updateUsr}
    , UPDATE_DT             = NOW()
WHERE
    PROJECT_ID = #{projectId}

UPDATE PROJECT_MASTER SET
    DEL_YN          = #{delYn}
    , UPDATE_USR    = #{updateUsr}
    , UPDATE_DT     = NOW()
WHERE
    PROJECT_ID = #{projectId}

